  assert.ok(Math.abs(hold.x - kindle.x) > 20 || Math.abs(hold.lift - kindle.lift) > 20, "not Ember");
  assert.ok(Math.abs(hold.x - bun.x) > 20 || Math.abs(hold.lift - bun.lift) > 20, "not Nori");
