  assert.ok(Math.abs(hold.x - watch.x) > 20 || Math.abs(hold.lift - watch.lift) > 20, "not Pip");
  assert.ok(Math.abs(hold.x - wheek.x) > 20 || Math.abs(hold.lift - wheek.lift) > 20, "not Whee");
  assert.ok(Math.abs(hold.x - scent.x) > 20 || Math.abs(hold.lift - scent.lift) > 20, "not Rue");
