  const field = P.fieldPoint(WIN, P.SPRITE, WORK);
  const circle = P.circlePoint(WIN, 0, P.SPRITE, WORK, 1);
  const dust = P.dustPoint(WIN, P.SPRITE, WORK);
  const bask = P.baskPoint(WIN, P.SPRITE, WORK);
  const kindle = P.kindlePoint(WIN, P.SPRITE, WORK);
  const bun = P.bunPoint(WIN, P.SPRITE, WORK);
  const write = P.writePoint(WIN, 0, P.SPRITE, WORK);
  const inspect = P.inspectPoint(WIN, "left", 0, P.SPRITE, WORK);
  const saddle = P.saddlePoint(WIN, "left", P.SPRITE, WORK);
  const flip = P.flipPoint(WIN, P.SPRITE, WORK);
  const patrol = P.patrolPoint(WIN, 0, P.SPRITE, WORK);
  const loop = P.loopPoint(WIN, P.SPRITE, WORK);
  const mosaic = P.mosaicPoint(WIN, P.SPRITE, WORK);
  const stone = P.stonePoint(WIN, "left", P.SPRITE, WORK);
  const chart = P.chartPoint(WIN, 0, P.SPRITE, WORK);
  const lid = P.lidPoint(WIN, P.SPRITE, WORK);
